import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Session } from '../../core/session';
import { Sheets } from '../../core/sheet';
import { PeopleList } from '../people/people';
import { RatesPanel } from '../rates/rates';

// The one screen: sign in by name, then choose a sheet by id. Everything else is per sheet.
@Component({
  selector: 'app-home',
  imports: [ReactiveFormsModule, PeopleList, RatesPanel],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form [formGroup]="sheetForm" (ngSubmit)="loadSheet()" aria-label="Load a sheet">
        <label for="sheet-id">Sheet id</label>
        <input id="sheet-id" data-testid="sheet-id-input" formControlName="id" autocomplete="off" />
        <button type="submit" data-testid="sheet-load" [disabled]="loading()">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-load-error">{{ err }}</p>
        }
      </form>

      @if (sheets.current(); as sheet) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ sheet.id }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ sheet.today }}</strong></p>

        <form [formGroup]="todayForm" (ngSubmit)="saveToday()" aria-label="Change the sheet's today">
          <label for="sheet-today-input">Change today</label>
          <input id="sheet-today-input" type="date" data-testid="sheet-today-input" formControlName="today" />
          <button type="submit" data-testid="sheet-today-save" [disabled]="savingToday()">Set today</button>
          @if (todayError(); as err) {
            <p role="alert" data-testid="sheet-error">{{ err }}</p>
          }
        </form>

        <app-rates />
        <app-people />
      } @else {
        <p data-testid="sheet-none">Load a sheet to begin.</p>
      }
    } @else {
      <form [formGroup]="signInForm" (ngSubmit)="signIn()" aria-label="Sign in">
        <label for="signin-name">Your name</label>
        <input id="signin-name" data-testid="signin-name" formControlName="name" autocomplete="username" />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signInError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly sheets = inject(Sheets);

  protected readonly signInForm = new FormGroup({
    name: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly sheetForm = new FormGroup({
    id: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly todayForm = new FormGroup({
    today: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly signInError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayError = signal<string | null>(null);
  protected readonly loading = signal(false);
  protected readonly savingToday = signal(false);

  constructor() {
    // An error is removed as soon as its form is changed.
    this.signInForm.valueChanges.subscribe(() => this.signInError.set(null));
    this.sheetForm.valueChanges.subscribe(() => this.sheetError.set(null));
    this.todayForm.valueChanges.subscribe(() => this.todayError.set(null));
  }

  protected signIn(): void {
    this.signInError.set(null);
    const name = this.signInForm.controls.name.value.trim();
    if (!name) {
      this.signInError.set('Type your name to sign in.');
      return;
    }
    this.session.signIn(name).subscribe({
      error: () => this.signInError.set('Could not sign in with that name.'),
    });
  }

  protected loadSheet(): void {
    // A second submit before the first has answered is ignored.
    if (this.loading()) return;
    this.sheetError.set(null);
    const id = this.sheetForm.controls.id.value.trim();
    if (!id) {
      this.sheetError.set('Type a sheet id to load.');
      return;
    }
    this.loading.set(true);
    this.todayError.set(null);
    this.sheets.load(id).subscribe({
      next: (sheet) => {
        this.loading.set(false);
        this.todayForm.setValue({ today: sheet.today }, { emitEvent: false });
      },
      error: () => {
        this.loading.set(false);
        this.sheetError.set('Could not load that sheet.');
      },
    });
  }

  protected saveToday(): void {
    // A second submit before the first has answered is ignored.
    if (this.savingToday()) return;
    this.todayError.set(null);
    const sheet = this.sheets.current();
    const today = this.todayForm.controls.today.value.trim();
    if (!sheet) return;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.todayError.set('Choose a date for today.');
      return;
    }
    this.savingToday.set(true);
    this.sheets.setToday(sheet.id, today).subscribe({
      next: () => this.savingToday.set(false),
      error: () => {
        this.savingToday.set(false);
        this.todayError.set('Could not change the sheet\'s today.');
      },
    });
  }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The figures of a sheet as the screen shows them: each person's claimed and due-total, and the
 * sheet's claimed-total and due-total. A change takes the figures before it and, once made, records
 * a ROLLUP line for each person whose figures moved and a TOTALS line when the sheet's totals moved.
 */
@Service
public class Rollup {

    /** A person's figures: claimed and due-total, each with two decimals; due-total is "n/a" when they have none. */
    public record PersonFigures(String name, String claimed, String dueTotal) {
    }

    /** A sheet's figures: each person's, by id in the order they were added, and the sheet's totals. */
    public record Figures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal) {
    }

    private static final String NOT_AVAILABLE = "n/a";

    private final SheetRepository sheets;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final Audit audit;

    public Rollup(SheetRepository sheets, PersonRepository people, ClaimRepository claims, RateRepository rates,
            Audit audit) {
        this.sheets = sheets;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Figures of(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<Long, PersonFigures> byPerson = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Rate> gradeRates = sheetRates.stream().filter(r -> r.getGrade().equals(person.getGrade())).toList();
            List<Claim> counting = sheetClaims.stream()
                    .filter(c -> c.getPersonId().equals(person.getId()) && c.getStatus().counts())
                    .toList();
            BigDecimal claimed = counting.stream().map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            // As on screen: with no rate in force today and no fixed figure, the person has no due-total.
            boolean anyFixed = counting.stream().anyMatch(c -> c.getSettledDue() != null || c.getStatedDue() != null);
            String due = NOT_AVAILABLE;
            if (anyFixed || (today != null && Rate.inForceOn(gradeRates, today).isPresent())) {
                BigDecimal total = counting.stream().map(c -> dueOf(c, gradeRates))
                        .filter(Objects::nonNull)
                        .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
                dueTotal = dueTotal.add(total);
                due = total.toPlainString();
            }
            byPerson.put(person.getId(), new PersonFigures(person.getName(), claimed.toPlainString(), due));
        }
        return new Figures(byPerson, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /**
     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
     * for each person whose figures changed (one who did not exist before counting as changed), then a
     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
     */
    public void recordChanges(String sheetId, String user, Figures before) {
        Figures after = of(sheetId);
        after.people().forEach((id, figures) -> {
            PersonFigures was = before.people().get(id);
            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal());
            }
        });
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
    }

    /** A claim's due: its settled figure, else its stated one, else its amount at its grade's rate in force on its date. */
    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        if (claim.getStatedDue() != null) {
            return claim.getStatedDue();
        }
        return Rate.inForceOn(gradeRates, claim.getDate())
                .map(rate -> ClaimService.dueOn(claim.getAmount(), rate.getRate())).orElse(null);
    }
}
